import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 10

// thresholdsFile 是低库存阈值配置，相对仓库根定位。
const thresholdsFile = "config/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值；没配置的仓库回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := loadThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取并解析阈值配置。
//
// 文件不存在、读不出来、内容不是 JSON 对象时返回 ok=false，调用方回退默认值。
func loadThresholds() (map[string]int, bool) {
	path, ok := findThresholdsFile()
	if !ok {
		return nil, false
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	return thresholds, true
}

// findThresholdsFile 从当前目录向上查找 thresholdsFile，返回第一个存在的路径。
func findThresholdsFile() (string, bool) {
	dir, err := os.Getwd()
	if err != nil {
		return "", false
	}
	for {
		candidate := filepath.Join(dir, thresholdsFile)
		if _, err := os.Stat(candidate); err == nil {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

