package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

func TestTmpVerifyThresholds(t *testing.T) {
	root, err := filepath.Abs("..")
	if err != nil {
		t.Fatal(err)
	}
	cfg := filepath.Join(root, "config", "thresholds.json")
	orig, err := os.ReadFile(cfg)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = os.WriteFile(cfg, orig, 0o644) })

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("configured shanghai = %d, want 20", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("unconfigured chengdu = %d, want %d", got, DefaultLowStockThreshold)
	}
	if !IsLowStock("shanghai", 19) || IsLowStock("shanghai", 20) {
		t.Fatal("IsLowStock strict-less-than broken for configured warehouse")
	}

	cases := []struct {
		name    string
		content []byte
		remove  bool
	}{
		{"missing", nil, true},
		{"invalid-json", []byte("{"), false},
		{"non-object-array", []byte("[1,2]"), false},
		{"non-object-number", []byte("5"), false},
		{"null", []byte("null"), false},
	}
	for _, tc := range cases {
		if tc.remove {
			_ = os.Remove(cfg)
		} else {
			if err := os.WriteFile(cfg, tc.content, 0o644); err != nil {
				t.Fatal(err)
			}
		}
		if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
			t.Fatalf("%s: shanghai = %d, want fallback %d", tc.name, got, DefaultLowStockThreshold)
		}
	}
}
